#include <math.h>

MagickBooleanType AutoGammaImage(Image *image, ExceptionInfo *exception) {
  if (image == NULL || exception == NULL)
    return MagickFalse;

  double mean = 0.0;
  double gamma = 0.0;

  if (image->channel_mask == DefaultChannel) {
    mean = GetImageMean(image, exception);
    if (mean <= 0.0) {
      return MagickFalse;
    }
    gamma = log10(mean);
    if (gamma <= 0.0) {
      return MagickFalse;
    }
    return SetImageGamma(image, gamma, exception);
  }

  for (ChannelType channel = 0; channel < MaxChannel; channel++) {
    if (image->channel_mask & (1ULL << channel)) {
      mean = GetImageMean(image, exception);
      if (mean <= 0.0) {
        return MagickFalse;
      }
      gamma = log10(mean);
      if (gamma <= 0.0) {
        return MagickFalse;
      }
      if (!SetImageGamma(image, gamma, exception)) {
        return MagickFalse;
      }
    }
  }

  return MagickTrue;
}
